<script setup lang="ts">import {onMounted,ref,computed} from 'vue';import {useRouter} from 'vue-router';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {download,date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import PairFamilyTable from '../components/PairFamilyTable.vue';const research=useResearch(),auth=useAuth(),router=useRouter(),{error,busy,perform}=useTask(),runId=ref(0),message=ref(''),completed=computed(()=>research.runs.filter(r=>r.status==='completed')),usableRuns=computed(()=>completed.value.filter(r=>!r.quality.invalidated)),current=computed(()=>completed.value.find(r=>r.id===runId.value)),selectedRun=computed(()=>research.runs.find(r=>r.id===runId.value));onMounted(()=>perform(async()=>{await Promise.all([research.loadRuns(),research.loadNotes()]);runId.value=usableRuns.value.find(r=>r.id===research.selected)?.id||usableRuns.value[0]?.id||completed.value[0]?.id||0}));async function submit(e:Event){const form=e.target as HTMLFormElement,f=new FormData(form);await research.addNote({name:f.get('name'),run_id:runId.value,rationale:f.get('rationale')});message.value='复检说明已提交，等待负责人审阅。';(form.elements.namedItem('name') as HTMLInputElement).value='';(form.elements.namedItem('rationale') as HTMLTextAreaElement).value=''}function openRun(id:number){research.select(id);router.push('/results')}async function review(e:Event,id:number){const f=new FormData(e.target as HTMLFormElement);await research.review(id,String(f.get('status')),String(f.get('reviewer_note')));message.value='审阅决定已留档。'}</script><template><PageHeading no="05" title="复检说明" sub="把完整家族的证据交给人工讨论，说明下一批独立试样如何复检。"/><ErrorNotice :error="error"/><p v-if="message" role="status" class="success">{{message}}</p><div class="note-spread"><section><h2 class="ruled-title">记录独立复检问题</h2><div v-if="!completed.length" class="empty">先完成一项秩检验，再提出有冻结依据的复检说明。</div><div v-else-if="!usableRuns.length" class="empty">已完成任务的依据都因失效试样停用。撤销通告也不能恢复旧依据，请在来源页核对后新建检验。</div><form v-else @submit.prevent="e=>perform(()=>submit(e))"><label>依据检验<select aria-label="复检依据任务" v-model.number="runId"><option v-for="r in usableRuns" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}{{r.quality.invalidated?' · 依据停用':''}}</option></select></label><p v-if="selectedRun?.quality.invalidated" class="quality-banner"><b>依据停用</b><span>{{selectedRun.quality.invalidated_reason||('命中通告 #'+selectedRun.quality.invalidated_by_notice_ids.join('、#'))}}。不能据此提出或批准新说明；撤销通告只影响新检验。</span></p><label>说明名称<input name="name" required minLength="2" maxLength="140"/></label><label>复检依据与独立样本方案<textarea name="rationale" rows="6" required minLength="10" maxLength="2000" placeholder="同时讨论未拒绝与拒绝组对、并列和分布形状；说明新的独立试样设计，不把p当作工艺性能概率。"/></label><button class="primary" :disabled="busy||!auth.canEdit||selectedRun?.quality.invalidated">提交复检审阅 →</button></form><details v-if="current" class="edit-fold"><summary>查阅依据检验的完整组对家族</summary><PairFamilyTable :pairs="current.result.pairs" :alpha="current.alpha"/></details><aside class="margin-note">批准的是复检说明。系统不会自动判定工艺优劣、改写等级或追加数据；已审阅决定不可覆盖，修订时另建说明。</aside></section><section><h2 class="ruled-title">负责人批注 <small>{{research.notes.length}}份</small></h2><div v-if="!research.notes.length" class="empty">尚无复检说明。保留全家族证据后，提出具体的独立样本问题。</div><article class="note-entry" v-for="n in research.notes" :key="n.id"><div class="entry-line"><small>NOTE {{n.id}}</small><StatusBadge :status="n.status"/></div><h3>{{n.name}}</h3><p class="rationale">{{n.rationale}}</p><small>依据任务 #{{n.run_id}} / {{date(n.created_at)}} / <button class="text-link inline-link" @click="openRun(n.run_id)">在结果页查看依据与排除 →</button></small><div v-if="n.quality.invalidated" class="quality-banner"><b>依据停用 · 不可分发</b><span>{{n.quality.invalidated_reason||('命中通告 #'+n.quality.invalidated_by_notice_ids.join('、#'))}}。批注与批准说明仍可查，CSV 分发与新建说明均被拒绝。</span></div><div v-if="n.reviewer_note" class="reviewer-note"><b>负责人批注</b><p>{{n.reviewer_note}}</p><small>{{n.reviewed_by}}</small></div><form v-if="auth.user?.role==='admin'&&n.status==='draft'&&!n.quality.invalidated" @submit.prevent="e=>perform(()=>review(e,n.id))"><label>审阅批注<textarea name="reviewer_note" minLength="5" maxLength="1000" required/></label><div class="button-row"><select name="status" aria-label="审阅决定"><option value="approved">同意复检</option><option value="rejected">退回补充</option></select><button :disabled="busy">留档决定</button></div></form><button v-if="n.status==='approved'&&!n.quality.invalidated" class="text-link" @click="perform(()=>download(n.id))">下载复检说明与完整组对 CSV ↙</button><span v-else-if="n.status==='approved'" class="muted">依据已停用，CSV 分发被拒绝；留档仍可阅读。</span></article></section></div></template>